# region texts written for this site (tag, description) and the design notes shown on each region page
REG = {
 'demacia':("A shining kingdom built on law, steel, and a deep fear of magic.","Demacia walls itself off with petricite, a white stone that dampens magic, and its people are taught that mages are dangerous. That rule is starting to crack, and some of the kingdom's own heroes are hiding the very power it hunts."),
 'noxus':("An empire that takes anyone in, as long as they can prove their strength.","Noxus expands by conquest, but it doesn't care where you were born. Anyone can rise if they are strong enough. Behind its generals, old powers like the Black Rose still fight over who really pulls the strings."),
 'piltover':("The City of Progress, where hextech makes fortunes.","Piltover controls the trade canal between two continents and grew rich on it. Hextech, a blend of magic and engineering, made its inventors famous. Its wealth sits directly on top of Zaun, and neither city forgets it."),
 'zaun':("The undercity beneath Piltover, choking on chemtech and ambition.","Zaun lives in the smog below Piltover's gleaming towers. Chem-barons run its streets, chemtech keeps it alive, and its people are tougher and stranger for it. This is where Jinx, Ekko, and Viktor come from."),
 'freljord':("A frozen land of rival tribes and buried ancient gods.","The Freljord is a harsh frozen north split between warring tribes. Three of them are led by women who each claim the ancient right to rule. Below the ice, the Watchers wait for someone to wake them."),
 'ionia':("An island of spirit magic, still healing from the Noxian invasion.","Ionia is a land where nature and spirit live side by side. Noxus invaded and was pushed back, but the war split the Ionians over a hard question: should they stay peaceful, or become as ruthless as their enemy?"),
 'shurima':("A fallen desert empire whose emperor has risen again.","Shurima once ruled most of the world through godlike Ascended warriors. Then it fell, betrayed from within. Now its emperor Azir has returned from the sand, and the old feuds have woken up with him."),
 'targon':("A mountain that reaches the stars, where gods choose mortal hosts.","Mount Targon is so tall it seems to touch the heavens. Those who reach the summit may be chosen by an Aspect, a celestial being that takes a mortal host. Sun and moon worshippers below it have been at war for centuries."),
 'bilgewater':("A lawless port of pirates, monsters, and debts.","Bilgewater is a port town with no real government, only captains, gangs, and sea monsters. Fortune and death are always one bad deal apart. Its old pirate king fell, and a new captain now runs the docks."),
 'shadowisles':("Once blessed islands, now drowned in the Black Mist.","The Blessed Isles were a place of healing until a grieving king tried to bring his wife back from the dead. The magic broke, and the Black Mist swallowed everything. Now the dead there can't rest, and they keep spreading."),
 'bandle':("Home of the yordles, found only by those it lets in.","Bandle City exists half in the spirit realm, and the doorway moves. Yordles are small, magical, and endlessly curious. They wander the world, and they usually know far more than they let on. Reload the page and its gate will be somewhere else."),
 'ixtal':("Hidden jungle kingdom of elemental mages.","Ixtal hid itself in the deep jungle during the Rune Wars and has stayed apart from the rest of the world ever since. Its rulers command the elements, and its forests hold some of the deadliest hunters alive."),
 'void':("A hungry nothing pressing in from beneath the world.","The Void is not a place so much as a hunger. It broke through at Icathia in ancient times and has been trying to unmake Runeterra ever since. Its creatures adapt, consume, and some of them learn to think."),
 'wanderers':("Gods, monsters and travellers who answer to no nation.","Not every legend has a homeland. Some are older than the nations themselves, like the Darkin and the Aspects' fallen kin. Others walk between realms, guard the runes that shaped the world, or simply hunt wherever they please. They turn up in every region's story, and none of them belong to just one."),
}
DNA = {
 'piltover':("Hextech: magic tamed by science and precision","Polished brass, white marble, blue hexcrystal","Symmetry, clean geometry, tall verticals","New York Art Deco, the look Arcane gave the upper city"),
 'zaun':("Chemtech: magic pulled from chemicals, toxic and unstable","Rusted iron, glass tanks, neon tubes, upcycled scrap","Asymmetric, handmade, organic flourishes","European Art Deco and Victorian industry, Arcane's dark mirror of Piltover"),
 'demacia':("Feared and suppressed by petricite, the stone that dampens it","White petricite, polished steel, gold leaf, royal blue","Upswept wings, shields, noble symmetry","High medieval chivalry and cathedral stonework"),
 'noxus':("A weapon like any other, owned by whoever is strongest","Raw concrete, black iron, crimson cloth, cracked stone","Heavy, low, spiked, brutalist","The brutalist look of Riot's Welcome to Noxus cinematic"),
 'freljord':("True Ice and the will of ancient demigods","Glacier ice, furs, carved bone and pine","Shards, runes, jagged peaks","Norse and Siberian sagas"),
 'ionia':("Spirit magic, woven into land and living things","Living wood, silk, ink, spirit blossoms","Flowing curves, brushstrokes, balance","East Asian ink painting and temple gardens"),
 'shurima':("Ascension, granted by the Sun Disc","Sandstone, beaten gold, lapis, linen","Discs, rays, stepped pyramids","Ancient desert empires"),
 'targon':("Celestial Aspects that descend into mortal hosts","Starlight, mountain granite, celestial metal","Peaks, constellations, sun and moon","Astronomy and mountain pilgrimage"),
 'bilgewater':("Sea gods, cursed relics and bargains with the deep","Salt-worn timber, tarred rope, brass, ink tattoos","Hull curves, hooks, coiled rope","Pirate ports and the age of sail"),
 'shadowisles':("The Black Mist, born from the Ruination","Ruined white stone, rusted chains, spectral light","Gothic arches, broken lines, curling wisps","Gothic ruins and ghost stories"),
 'bandle':("Wild yordle magic from the spirit realm","Moss, toadstools, glitter, borrowed trinkets","Spirals, round shapes, nothing quite matching","Fairy tales and hidden doors"),
 'ixtal':("Mastery of the elements: earth, water, fire and wind","Jade, carved limestone, jungle growth","Stepped pyramids, fret patterns, geometric glyphs","Mesoamerican temple cities"),
 'void':("Unmaking: it consumes, adapts and grows","Chitin, violet crystal, living tissue","Spikes, eyes, fractal growth","Cosmic horror"),
 'wanderers':("World Runes, Darkin blades and cosmic power older than any nation","Starlight, rune-carved stone, ancient bronze","Circles, orbits, runic glyphs","Myth and folklore that cross every border"),
}
for k,(a,b) in REG.items(): EN['rg_'+k+'_tag']=a; EN['rg_'+k+'_desc']=b
